/**
 * Package capability service skeleton (WS-7.3 / WS-8).
 *
 * Generated by `pnpm init:web` from
 * `standards/web-scaffold/hosted-runtime/capability-service-skeleton.ts`. The hosted runtime
 * handles the protocol-owned capabilities (`system.*`, `web.surface.*`) and routes everything
 * else here. Capabilities listed in `agent/web-execution.json` are executed in the connected
 * page through the standard Web Channel before this module is consulted; this service owns the
 * server-side remainder.
 *
 * Replace the `capability_not_implemented` stub with real use-case dispatch as the package grows;
 * keep every business rule here (or behind it) so the page and the Agent share one contract.
 */

export interface CapabilityExecutionContext {
  readonly audience: "agent" | "browser" | "host";
  /** Present when the App Agent invokes from a bound package session. */
  readonly bindingId?: string;
  readonly turnId?: string;
  readonly toolCallId?: string;
  readonly origin?: string;
  /** Present only when the App granted a user confirmation for this invoke (optional). */
  readonly confirmation?: { readonly granted: true; readonly at?: string };
}

export async function executeCapability(
  capabilityId: string,
  input: Record<string, unknown>,
  context: CapabilityExecutionContext,
): Promise<unknown> {
  void input;
  void context;
  const error = new Error(`capability is not implemented: ${capabilityId}`);
  Object.assign(error, {
    code: "capability_not_implemented",
    category: "capability",
    retryable: false,
  });
  throw error;
}

export function close(): void {
  // Close repositories, handles and other package resources here (maintenance support).
}
